import { AnimatedTouchableOpacity } from '@/components'
import { Text, View, ViewStyle } from 'react-native'
import { defineStyles } from '@/utils/defineStyles'
import * as Haptics from 'expo-haptics'
import { colors } from '@/theme'

interface SignUpButtonProps {
	variant: 'dark' | 'light' | 'white'
	animatedStyle: ViewStyle
	onPress: () => void
	iconComponent: React.ReactNode
	label: string
}

export const SignUpButton = ({
	variant,
	animatedStyle,
	onPress,
	iconComponent,
	label
}: SignUpButtonProps) => {
	const handlePress = () => {
		Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium)
		onPress()
	}

	return (
		<AnimatedTouchableOpacity
			style={[styles.authButtonContainer, animatedStyle, styles[variant]]}
			onPress={handlePress}
		>
			<View style={styles.authButtonIconComponent}>{iconComponent}</View>
			<Text style={[styles.authButtonLabel, styles[`${variant}Text`]]}>
				{label}
			</Text>
		</AnimatedTouchableOpacity>
	)
}

const styles = defineStyles({
	authButtonContainer: {
		borderRadius: 18,
		width: '100%',
		height: 52,
		justifyContent: 'center',
		alignItems: 'center',
		flexDirection: 'row',
		gap: 12
	},
	authButtonIconComponent: {},
	authButtonLabel: {
		fontSize: 16,
		fontWeight: '500',
		color: colors.light.gray[900]
	},
	dark: {
		backgroundColor: colors.light.gray[900]
	},
	light: {
		backgroundColor: colors.light.gray[50]
	},
	white: {
		backgroundColor: colors.light.gray[25]
	},
	darkText: {
		color: colors.light.gray[25]
	},
	lightText: {
		color: colors.light.gray[900]
	},
	whiteText: {
		color: colors.light.gray[900]
	}
})
